import { S3 } from '@aws-sdk/client-s3';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand, GetRoleCommand, UpdateAssumeRolePolicyCommand, Role } from '@aws-sdk/client-iam';
import { randomUUID } from 'crypto';

export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying resource type which paigo connects to. Default is s3.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public datastoreType?: SupportedDatastores;

    /**
     * The platform where the datastore is hosted. Default is 's3'.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 's3' })
    public platform?: string;

    /**
     * The region where the datastore is hosted. Default is 'us-east-1'.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    /**
     * The customer's AWS account ID.
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '123456789012' })
    public accountId: string;

    /**
     * The IAM role ARN created by Paigo for ingestion.
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public iamRoleArn?: string;

    /**
     * The external ID for the IAM role trust policy.
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public externalId?: string;

    /**
     * The ingestion bucket prefix.
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public ingestion?: string;

    /**
     * The DLQ bucket prefix.
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public dlq?: string;

    /**
     *
     * Whether paigo is hosting the ingestion endpoint, or it is hosted by the client. Optional, default is `true`.
     * @example 'true'
     */
    @IsString()
    @IsOptional()
    public paigoHosted?: 'true';

    /**
     *
     * What is the cloud environment associated with the ingestion endpoint. Optional, default is `aws`.
     * @example "aws"
     */
    @IsEnum(supportedCloudPlatforms)
    @IsOptional()
    public hostedCloud?: supportedCloudPlatforms;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                cloudId,
                hostedCloud,
                paigoHosted,
                datastoreType,
                businessID,
                platform,
                region,
                accountId,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
            } = datastoreAccessInformation;
            this.cloudId = cloudId;
            this.hostedCloud = hostedCloud ? hostedCloud : supportedCloudPlatforms.aws;
            this.paigoHosted = paigoHosted ? paigoHosted : 'true';
            this.datastoreType = datastoreType ? datastoreType : SupportedDatastores.s3;
            this.businessID = businessID;
            this.platform = platform ? platform : 's3';
            this.region = region ? region : 'us-east-1';
            this.accountId = accountId;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const {
                datastoreType: supportedDbs,
                paigoHosted,
                hostedCloud,
                cloudId,
                platform,
                region,
                accountId,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
            } = datastoreAccessInformation;
            if (supportedDbs) influxPoint.tag('supportedDbs', supportedDbs);
            if (paigoHosted) influxPoint.tag('paigoHosted', paigoHosted);
            if (hostedCloud) influxPoint.tag('hostedCloud', hostedCloud);
            if (cloudId) influxPoint.tag('cloudId', cloudId);
            if (platform) influxPoint.tag('platform', platform);
            if (region) influxPoint.tag('region', region);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        datastoreType,
        paigoHosted,
        hostedCloud,
        cloudId,
        businessID,
        platform,
        region,
        accountId,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            datastoreType,
            paigoHosted,
            hostedCloud,
            cloudId,
            businessID,
            platform,
            region,
            accountId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
        });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID, accountId, region, measurementId } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3) {
            const iamClient = new IAMClient({ region: region || process.env.AWS_REGION || 'us-east-1' });
            const s3 = new S3({ region: region || process.env.AWS_REGION || 'us-east-1' });

            const roleName = `datastore-${businessID}-${measurementId}`;
            const externalId = randomUUID();
            const ingestionPrefix = `${businessID}/ingestion/`;
            const dlqPrefix = `${businessID}/dlq/`;

            const trustPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Principal: {
                            AWS: `arn:aws:iam::${accountId}:root`,
                        },
                        Action: 'sts:AssumeRole',
                        Condition: {
                            StringEquals: {
                                'sts:ExternalId': externalId,
                            },
                        },
                    },
                ],
            };

            try {
                await iamClient.send(
                    new CreateRoleCommand({
                        RoleName: roleName,
                        AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                        Description: `Paigo datastore ingestion role for business ${businessID} measurement ${measurementId}`,
                        MaxSessionDuration: 3600,
                    })
                );
            } catch (e) {
                if (e.name === 'EntityAlreadyExistsException') {
                    const existingRole = await iamClient.send(new GetRoleCommand({ RoleName: roleName }));
                    if (existingRole.Role) {
                        await iamClient.send(
                            new UpdateAssumeRolePolicyCommand({
                                RoleName: roleName,
                                PolicyDocument: JSON.stringify(trustPolicy),
                            })
                        );
                    }
                } else {
                    throw e;
                }
            }

            const policyDocument = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${ingestionPrefix}*`,
                        ],
                    },
                    {
                        Effect: 'Allow',
                        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${dlqPrefix}*`,
                        ],
                    },
                ],
            };

            await iamClient.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: 'PaigoDatastoreIngestionPolicy',
                    PolicyDocument: JSON.stringify(policyDocument),
                })
            );

            const roleArn = `arn:aws:iam::${cloudId}:role/${roleName}`;

            dbAccessInformation.iamRoleArn = roleArn;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.ingestion = ingestionPrefix;
            dbAccessInformation.dlq = dlqPrefix;
            dbAccessInformation.platform = 's3';
            dbAccessInformation.region = region || process.env.AWS_REGION || 'us-east-1';

            try {
                const params = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                };
                const policy = await s3.getBucketPolicy(params);
                const policyJson = JSON.parse(policy.Policy);
                const statement = policyJson.Statement;
                const rootAccount = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`],
                };
                statement.push(rootAccount);
                const newPolicy = { ...policyJson };
                newPolicy.Statement = statement;
                const newParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                    Policy: JSON.stringify(newPolicy),
                };
                await s3.putBucketPolicy(newParams);

                const dlqParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                };
                const dlqPolicy = await s3.getBucketPolicy(dlqParams);
                const dlqPolicyJson = JSON.parse(dlqPolicy.Policy);
                const dlqStatement = dlqPolicyJson.Statement;
                const rootAccountForDLQ = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`],
                };
                dlqStatement.push(rootAccountForDLQ);
                const newDLQPolicy = { ...dlqPolicyJson };
                newDLQPolicy.Statement = dlqStatement;
                const newDLQParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                    Policy: JSON.stringify(newDLQPolicy),
                };
                await s3.putBucketPolicy(newDLQParams);
            } catch (e) {
                if (e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`AccountId: ${accountId} is invalid`);
                } else {
                    throw e;
                }
            }
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, datastoreType, accountId, iamRoleArn, externalId, businessID, measurementId, region } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3 && iamRoleArn && externalId) {
            const iamClient = new IAMClient({ region: region || process.env.AWS_REGION || 'us-east-1' });

            const trustPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Principal: {
                            AWS: `arn:aws:iam::${accountId}:root`,
                        },
                        Action: 'sts:AssumeRole',
                        Condition: {
                            StringEquals: {
                                'sts:ExternalId': externalId,
                            },
                        },
                    },
                ],
            };

